    key='parametres-train' if group['name']=='Entrainement' else 'parametres-risque'
    intro='<h1>'+('Param&egrave;tres d\'entra&icirc;nement' if key.endswith('train') else 'R&egrave;gles &eacute;conomiques et risque')+'</h1><p>Valeurs et bornes extraites des sch&eacute;mas Python actifs. Ce ne sont pas les r&eacute;glages de ta session ni des valeurs optimales. Pour les modifier, utilise les formulaires correspondants. Toute comparaison doit consigner ces choix.</p>'
    for item in group['items']:
        limits=item['limits'];bounds=[]
        if 'enum' in limits:bounds.append('Choix : '+', '.join(str(x) for x in limits['enum']))
        for k,label in [('minimum','minimum inclus'),('maximum','maximum inclus'),('exclusiveMinimum','strictement au-dessus de'),('exclusiveMaximum','strictement au-dessous de')]:
            if k in limits:bounds.append(label+' '+str(limits[k]))
        if item['key']=='multipliers':bounds=['3 valeurs, chacune entre 1.01 et 100 inclus']
        if not bounds:bounds=['Vrai / faux' if limits.get('type')=='boolean' else str(limits)]
        intro+='<div class="parameter" id="p-'+item['key']+'"><div class="row"><h2>'+html.escape(item['title'])+'</h2><code>'+item['key']+'</code></div><div class="parameter-meta"><span>D&eacute;faut <b>'+html.escape(json.dumps(item['default']))+'</b></span><span>'+html.escape(item['unit'])+'</span><span>'+html.escape('; '.join(bounds))+'</span></div><p>'+html.escape(item['description'])+'</p><p class="param-caution">'+html.escape(item['caution'])+'</p></div>'
    ch(key, 'Param&egrave;tres / '+('entra&icirc;nement' if key.endswith('train') else '&eacute;conomie'),group['source'],intro)

